describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10000 * 10% = 1000
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy always returns 0, so this tests the Math.max(0, ...) path
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // Same as sum: 1000 + 200 = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("chains discounts sequentially on remaining subtotal", () => {
      // 10% of 10000 = 1000 → remaining 9000
      // 200 from 9000 → remaining 8800
      // total discount = 1200
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(200),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("ordering matters in chain mode", () => {
      // Order A: fixed 5000 first, then 10% of remaining
      const orderA = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(5000),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      // 5000 off 10000 → remaining 5000 → 10% of 5000 = 500 → total 5500
      expect(orderA.computeDiscountCents(10000)).toBe(5500);

      // Order B: 10% first, then fixed 5000
      const orderB = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(5000),
        ],
        "chain",
      );
      // 10% of 10000 = 1000 → remaining 9000 → 5000 off → total 6000
      expect(orderB.computeDiscountCents(10000)).toBe(6000);
    });

    it("chain clamps each step to remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(8000),
          new FixedAmountDiscountPolicy(5000), // only 2000 remaining
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

