        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents(emptyLines, 5000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      const lines: CartLine[] = [
        { product: { id: "x", name: "X", unitPriceCents: 100 }, quantity: 3 },
      ];
      expect(calc.computeShippingCents(lines, 300)).toBe(0);
    });

    it("selects lowest bracket for light items", () => {
      const lines = [makeLine("a", 250, 1)]; // 250g ≤ 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const lines = [makeLine("a", 500, 1)]; // exactly 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket when exceeding boundary", () => {
      const lines = [makeLine("a", 501, 1)]; // 501g > 500g → 2000g bracket
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects middle bracket", () => {
      const lines = [makeLine("a", 1000, 1)]; // 1000g ≤ 2000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects heaviest bracket", () => {
      const lines = [makeLine("a", 3000, 1)]; // 3000g ≤ 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 6000, 1)]; // > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow set", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      const lines = [makeLine("a", 3000, 1)]; // > 2000g, no overflow
      expect(noOverflow.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sums weight across multiple lines", () => {
      // 200*3 + 400*1 = 1000g ≤ 2000g bracket
      const lines = [makeLine("a", 200, 3), makeLine("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 400, 1)]; // 400g ≤ 500g
      expect(unsorted.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

